  function createSvg(source, name) {
    const def = ICONS[name] || ICONS._fallback;
    const svg = document.createElementNS("http://www.w3.org/2000/svg", "svg");
    for (const attr of Array.from(source.attributes || [])) {
      if (attr.name !== "data-lucide") svg.setAttribute(attr.name, attr.value);
    }
    const currentClass = svg.getAttribute("class") || "";
    svg.setAttribute("class", (currentClass + " lucide lucide-" + name).trim());
    svg.setAttribute("viewBox", def.viewBox);
    svg.setAttribute("xmlns", "http://www.w3.org/2000/svg");
    svg.setAttribute("fill", "currentColor");
    svg.setAttribute("aria-hidden", svg.getAttribute("aria-hidden") || "true");
    svg.setAttribute("focusable", "false");
    if (!svg.getAttribute("width")) svg.setAttribute("width", "24");
    if (!svg.getAttribute("height")) svg.setAttribute("height", "24");
    svg.innerHTML = def.body;
    return svg;
  }

  function createIcons(options) {
    const root = options && options.root ? options.root : document;
    root.querySelectorAll("[data-lucide]").forEach(function (element) {
      const name = element.getAttribute("data-lucide") || "_fallback";
      if (element.tagName && element.tagName.toLowerCase() === "svg" && element.classList.contains("gabaritando-icon-ready")) return;
      const svg = createSvg(element, name);
      svg.classList.add("gabaritando-icon-ready");
      element.replaceWith(svg);
    });
  }

  window.lucide = { createIcons: createIcons, icons: ICONS, isLocalFallback: true };

